-- ------------------------------------------------------------
-- budgeting_pekerjaan
-- Rincian anggaran per pekerjaan & cluster (/budgeting)
-- 75 baris, 7 kolom
-- ------------------------------------------------------------
CREATE TABLE `budgeting_pekerjaan` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `cluster` TEXT NULL COMMENT 'Cluster',
  `pekerjaan` TEXT NULL COMMENT 'Pekerjaan',
  `total_anggaran` BIGINT NULL COMMENT 'Total Anggaran',
